// Which files are first-party, said once (SPEC code-graph section 4.0): a tracked file is excluded when (a) a path segment is
// third_party / vendor / node_modules, (b) .gitattributes marks it linguist-vendored or linguist-generated, (c) its first
// GENERATED_LINES lines carry @generated or DO NOT EDIT, (d) a project `code.exclude` glob matches it. The snapshot keeps each
// excluded file with its reason; an edge into one is kept with to_kind "excluded".
use crate::limits::GENERATED_LINES;
use crate::paths::{dirname, pattern_hits};

const VENDOR_SEGMENTS: [&str; 3] = ["third_party", "vendor", "node_modules"];
const ATTRS: [&str; 2] = ["linguist-vendored", "linguist-generated"];

pub struct Exclude {
    /// (dir of the .gitattributes, pattern, attribute, set) in the order git applies them: shallow files first, lines in order
    attrs: Vec<(String, String, &'static str, bool)>,
    globs: Vec<String>,
}

impl Exclude {
    pub fn new(gitattributes: &[(String, String)], globs: &[String]) -> Exclude {
        let mut files: Vec<&(String, String)> = gitattributes.iter().collect();
        files.sort_by_key(|(p, _)| (p.matches('/').count(), p.clone()));
        let mut attrs = vec![];
        for (p, text) in files {
            for l in text
                .lines()
                .map(str::trim)
                .filter(|l| !l.is_empty() && !l.starts_with('#'))
            {
                let mut it = l.split_whitespace();
                let Some(pat) = it.next() else { continue };
                for a in it {
                    let (name, set) = match a.strip_prefix('-') {
                        Some(n) => (n, false),
                        None => match a.split_once('=') {
                            Some((n, v)) => (n, v != "false"),
                            None => (a, true),
                        },
                    };
                    if let Some(&k) = ATTRS.iter().find(|&&k| k == name) {
                        attrs.push((dirname(p).to_string(), pat.to_string(), k, set));
                    }
                }
            }
        }
        Exclude {
            attrs,
            globs: globs.to_vec(),
        }
    }

    /// the reason `p` is excluded by its path alone (rules a, b, d); None = first-party so far
    pub fn why(&self, p: &str) -> Option<String> {
        if let Some(s) = p.split('/').find(|s| VENDOR_SEGMENTS.contains(s)) {
            return Some(format!("path segment {s}"));
        }
        for k in ATTRS {
            let last = self
                .attrs
                .iter()
                .rev()
                .find(|(b, pat, a, _)| *a == k && pattern_hits(pat, b, p));
            if let Some((.., true)) = last {
                return Some(k.to_string());
            }
        }
        self.globs
            .iter()
            .find(|g| pattern_hits(g, "", p))
            .map(|g| format!("code.exclude {g}"))
    }
}

/// rule (c): a generated-file header in the first lines
pub fn generated(src: &[u8]) -> bool {
    let head: Vec<&[u8]> = src.split(|&b| b == b'\n').take(GENERATED_LINES).collect();
    head.iter().any(|l| {
        let l = String::from_utf8_lossy(l);
        l.contains("@generated") || l.contains("DO NOT EDIT")
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn the_four_rules() {
        let x = Exclude::new(&[(".gitattributes".into(), "gen/** linguist-generated\nlib/*.js linguist-vendored\nlib/keep.js -linguist-vendored\n".into())], &["**/*.snap.py".into()]);
        assert_eq!(
            x.why("a/node_modules/b.js").as_deref(),
            Some("path segment node_modules")
        );
        assert_eq!(x.why("gen/x.py").as_deref(), Some("linguist-generated"));
        assert_eq!(x.why("lib/y.js").as_deref(), Some("linguist-vendored"));
        assert_eq!(x.why("lib/keep.js"), None);
        assert_eq!(
            x.why("t/a.snap.py").as_deref(),
            Some("code.exclude **/*.snap.py")
        );
        assert!(
            generated(b"// x\n// Code generated by y. DO NOT EDIT.\n")
                && !generated(b"1\n2\n3\n4\n5\n@generated\n")
        );
    }
}
